} else if (location.pathname.replace(/\/$/, "") === "/admin") {
  const app = document.querySelector("main");
  const esc = (value) => String(value ?? "").replace(/[&<>"']/g, (char) => ({ "&":"&amp;", "<":"&lt;", ">":"&gt;", '"':"&quot;", "'":"&#39;" })[char]);
  let adminPassword = "";
  app.innerHTML = '<section class="hero"><div class="eyebrow">Garage quotes</div><h1>Quote requests</h1><p class="intro">Sign in to manage customer quote requests.</p></section><section class="card admin-card"><label for="admin-password">Admin password</label><input id="admin-password" type="password" autocomplete="current-password" /><button class="cta" id="admin-login" type="button">Open requests</button><p class="status" id="admin-status" role="status"></p></section><p id="admin-new-count" class="admin-new-count"></p><div id="admin-requests"></div>';
  const status = document.getElementById("admin-status");
  const listRequests = async () => {
    status.textContent = "Loading quote requests...";
    try {
      const requests = await convex.action("admin:list", { password:adminPassword });
      document.getElementById("admin-new-count").textContent = requests.filter(item => item.status === "new").length + " new requests";
      status.textContent = requests.length ? requests.length + " quote request(s)." : "No quote requests yet.";
      const byId = new Map(requests.map(item => [item._id, item]));
      document.getElementById("admin-requests").innerHTML = requests.map(item => {
        const location = [item.area, item.city].filter(Boolean).filter((value,index,values) => values.findIndex(other => other.toLowerCase() === value.toLowerCase()) === index).join(", ");
        const parts = item.parts.map(part => '<li>' + esc(part.partName) + ' – ' + esc(part.workNeeded) + '</li>').join("");
        const photos = item.photoUrls.map((url,index) => url ? '<a href="' + esc(url) + '" target="_blank" rel="noopener"><img src="' + esc(url) + '" alt="Customer damage photo ' + (index+1) + '" loading="lazy" /></a>' : '').join("");
        return '<section class="card admin-request" data-id="' + esc(item._id) + '"><div class="admin-request-heading"><h3>' + esc(item.name) + '</h3>' + (item.status === "new" ? '<span class="admin-new-badge">New</span>' : '<span>' + esc(item.status) + '</span>') + '</div><p class="admin-customer-number">' + esc(item.whatsappNumber) + '</p><p><strong>' + esc(item.carModel) + '</strong><br>' + esc(location) + '</p><p class="admin-received">Received ' + esc(new Date(item.createdAt).toLocaleString("en-IN")) + '</p><ol class="admin-damage">' + parts + '</ol><div class="admin-photos">' + photos + '</div><div class="admin-actions"><button class="secondary" data-customer type="button">WhatsApp customer</button><button class="secondary" data-copy-garage type="button">Copy garage message</button><button class="secondary" data-sent type="button"' + (["sent", "sent to garages"].includes(item.status) ? ' disabled' : '') + '>Mark sent to garages</button></div><p class="status" data-request-status role="status"></p></section>';
      }).join("");
      document.querySelectorAll(".admin-request").forEach(card => {
        const id = card.dataset.id;
        const item = byId.get(id);
        const cardStatus = card.querySelector("[data-request-status]");
        card.querySelector("[data-customer]").addEventListener("click", () => {
          const digits = item.whatsappNumber.replace(/\D/g, "");
          const international = digits.length === 10 ? "91" + digits : digits;
          if (!/^\d{7,15}$/.test(international)) { cardStatus.textContent = "This saved customer number is invalid."; return; }
          window.open("https://wa.me/" + international, "_blank", "noopener");
        });
        card.querySelector("[data-copy-garage]").addEventListener("click", async () => {
          try { await navigator.clipboard.writeText(item.garageMessage); cardStatus.textContent = "Garage message copied."; }
          catch { cardStatus.textContent = "Could not copy the message. Please try again."; }
        });
        card.querySelector("[data-sent]").addEventListener("click", async event => {
          event.currentTarget.disabled = true;
          try { await convex.action("admin:markSent", {password:adminPassword,id}); await listRequests(); }
          catch (error) { cardStatus.textContent = error.message || "Could not update this request."; event.currentTarget.disabled = false; }
        });
      });
    } catch (error) { document.getElementById("admin-requests").innerHTML = ""; status.textContent = error.message || "Could not load quote requests."; }
  };
  document.getElementById("admin-login").addEventListener("click", () => { adminPassword = document.getElementById("admin-password").value; listRequests(); });
